def ver_files(i, extra=()):
    return [CAND % i + 'evidence.json', CAND % i + 'check.mjs', CAND % i + 'STATUS.json', CAND % i + 'HANDOFF.md', CAND % i + 'evidence/'] + list(extra)


RECORD = 'node candidates/r1h/_lib/record.mjs %s --evidence candidates/r1h/%s/evidence.json --test "node candidates/r1h/%s/check.mjs"'

A('vd10-8', area='data', route='verification-record', size='S',
  value='The 20th Maine is the most visited regiment of the site and its strength is printed from the data as 386 while another figure (358) stands elsewhere; the Official Records have not been read for it, and no page may print a strength before its source is on record.',
  files=ver_files('vd10-8'),
  touches=[],
  reads=['tmp/library/or27 (the three OCR parts) through tools/bt/or27_find.py and docs/battle-theatre/library/or27_index.json', 'release/R1g/dist/data (U-20ME)', 'docs/plan/STATUS/items-B.json (VD10-8)', 'candidates/r1h/README.md (verification-record route)'],
  acceptance=(
      'candidates/r1h/vd10-8/evidence.json ({question, method, outcome, points[]}) written from a reading of the Official Records, and check.mjs that re-checks every quotation and every repository citation and exits non-zero on any mismatch; record: ' + RECORD % ('vd10-8', 'vd10-8', 'vd10-8') + '. '
      'Question: what strength of the 20th Maine at Gettysburg do the Official Records give, and where do 386 (the data) and 358 (elsewhere) come from? Measured on 2026-11-16 with `python3 -I tools/bt/or27_find.py "Twentieth Maine" --part 1`: Barnes\'s report (OR27-1-R189, p. 603) reads in the OCR "The Twentieth Maine, Colonel Chamberlain commanding, was posted on the left. It consisted of 380 men and officers": the last digit is OCR and is not yet checked against the page; release/R1g/dist/data and the legacy data give U-20ME strength 386 (casualties 130 corrected to 125 by group DATA). '
      'Points to record, each with report id, author, printed page (the page marker as or27_find prints it, a "~" page recorded as interpolated), the figure as the OCR prints it and a verbatim quotation of at most 40 words that `python3 -I tools/bt/or27_find.py --verify "<quote>" --part 1` finds: (1) Chamberlain\'s own report, read, whether or not it states a number; (2) every other report that states the regiment\'s strength or that of the brigade with it (Barnes, Vincent, Rice, Sykes, the organization return of the army: say which give a figure and which do not); (3) the page-image check of each digit that decides between 380, 386 and 358 (one attempt, the scan page of the Internet Archive item named in tmp/library/or27/MANIFEST.json, at one request per second, saved under tmp/ not in git with its sha256; a refused host, a missing image or an unreadable digit is recorded as blocked or failed with the response, never worked around or guessed); (4) every place of 386 and of 358 in the repository (grep, file and line: release/R1g/dist/data and pages, data-src, docs) and the source each one names. '
      'Outcome per the record rules: confirmed (the data figure equals the one the report gives, with its page), refuted (it differs: both values with their pages) or mixed; a figure that no report gives is recorded as not found. This entry changes no data and no page: a corrected figure is a wp-data entry and a decision row of the historian (row C10: conflicting values are carried with their sources, none is chosen); HANDOFF.md names the entry that carries it. '
      'Not claimed: any figure from a source that is not in the local Official Records text or an image read in this run; the owner\'s search-console questions that share the item (whether landing.html was ever indexed, reliance on Bing).'),
  short='Read the Official Records for the 20th Maine strength (Chamberlain\'s own report, Barnes p. 603 "380", brigade returns), verify each quote with or27_find --verify, check the deciding digit on the page image once (blocked if refused), place 386 and 358 in the repo; evidence.json, check.mjs',
  owed='The page-image check needs archive.org (one attempt at one request per second); a corrected figure and the historian\'s decision are other entries.')

A('vd13-4', area='data', route='verification-record', size='S',
  value='The 1863 base map and the Battle Theatre need period maps; the question whether the 28 hourly Bachelder position maps exist digitally has never been put to the one catalogue that holds them and answers from this container.',
  files=ver_files('vd13-4'),
  touches=[],
  reads=['docs/basemap1863/SOURCES-roads.md', 'docs/plan/STATUS/items-B.json (VD13-4, VD14-9 item 3)', 'candidates/r1h/README.md (verification-record route)'],
  acceptance=(
      'candidates/r1h/vd13-4/evidence.json, the raw responses under candidates/r1h/vd13-4/evidence/ and check.mjs; record: ' + RECORD % ('vd13-4', 'vd13-4', 'vd13-4') + '. '
      'Question: do the 28 hourly position maps attributed to John B. Bachelder (the survey\'s wording: the number, the dates and the titles are what the catalogue records settle, not what this text says) exist as digital images in the Library of Congress, how many, under which call numbers and identifiers, and with which rights statement? '
      'Method: the public JSON interface of www.loc.gov (search and item records with fo=json; tile.loc.gov only to confirm an image address already in a record), at most 25 requests in all and never more than one per second (the log carries a timestamp per request and check.mjs asserts the spacing), no login, no captcha, no workaround of a refusal. Every raw response is saved (candidates/r1h/vd13-4/evidence/) and listed in evidence.json with its URL, date, HTTP status, byte count and sha256. '
      'Done when evidence.json records: the queries; for each map found the identifier, title, date, call number, number of images and rights statement exactly as the record states them (copied, nothing completed from memory); the count of distinct maps that are digitized and whether it is 28 (a count the records do not establish is recorded as not established, with the nearest figure and why); the outcome found, not-found (a failed lookup is recorded as failed) or blocked (a refused host with the response); check.mjs re-parses the saved responses and verifies every cited identifier, title and date against them and the sha256 of each file. '
      'No map image is downloaded into the product tree or scanned into a tree under git here (a rights check comes first and is the owner\'s); HANDOFF.md says how the result feeds docs/basemap1863/SOURCES-roads.md and the Battle Theatre period-map list, and that VD14-9 item 3 is this entry.'),
  short='Search the Library of Congress JSON interface (at most 25 requests, one per second, raw responses saved) for the 28 hourly Bachelder maps: identifiers, call numbers, rights, count digitized or not established; found, failed or blocked; check.mjs re-parses the saved responses',
  owed='Nothing in the product changes; a download or use of any map waits for a rights check (owner).')

